shouldSwitchTo(aArgs) {
  if (!this.tab) {
    return -1;
  }
  if (this.tab.pageLoaded) {
    // FIXME: selectPrefPane is async, but we can't await it here.
    this.tab.browser.contentWindow.selectPrefPane(
      aArgs.paneID,
      aArgs.scrollPaneTo,
      aArgs.otherArgs
    );
  }
  return document.getElementById("tabmail").tabInfo.indexOf(this.tab);
},
